    defect_qty=#{command.defectQty},revision_no=revision_no+1,updated_at=UTC_TIMESTAMP(6)
WHERE production_result_id=#{row.productionResultId} AND finished_lot_id=#{row.finishedLotId}
    AND revision_no=#{command.expectedRevision}

